  'highlights.editSelection.title': 'Edit selected text by voice',
  'highlights.editSelection.desc': 'Select a sentence in any app, press the selection hotkey and say what should change: "make it friendlier", "translate to English". WhisPaste rewrites the selection in place with Smart Mode. Off by default.',
  'highlights.cloud.title': 'Cloud, only if you want it',
